    EXCEPTION WHEN OTHERS THEN DBMS_OUTPUT.PUT_LINE('SKIP GT_SDPBP_FUTURE_PRICE_TEMP1_2 '||SQLERRM); END;
    BEGIN EXECUTE IMMEDIATE 'GRANT DELETE,INSERT,SELECT,UPDATE ON SCM_MGR.GT_SDPBP_FUTURE_PRICE_TEMP2_4 TO '||R.USERNAME; V_N:=V_N+1;
    EXCEPTION WHEN OTHERS THEN DBMS_OUTPUT.PUT_LINE('SKIP GT_SDPBP_FUTURE_PRICE_TEMP2_4 '||SQLERRM); END;
    BEGIN EXECUTE IMMEDIATE 'GRANT DELETE,INSERT,SELECT,UPDATE ON SCM_MGR.GT_SDPBP_FUTURE_PRICE_TEMP3_2 TO '||R.USERNAME; V_N:=V_N+1;
    EXCEPTION WHEN OTHERS THEN DBMS_OUTPUT.PUT_LINE('SKIP GT_SDPBP_FUTURE_PRICE_TEMP3_2 '||SQLERRM); END;
    BEGIN EXECUTE IMMEDIATE 'GRANT DELETE,INSERT,SELECT,UPDATE ON SCM_MGR.GT_SDPB_BP_FCST TO '||R.USERNAME; V_N:=V_N+1;
    EXCEPTION WHEN OTHERS THEN DBMS_OUTPUT.PUT_LINE('SKIP GT_SDPB_BP_FCST '||SQLERRM); END;
    BEGIN EXECUTE IMMEDIATE 'GRANT DELETE,INSERT,SELECT,UPDATE ON SCM_MGR.GT_SDPB_DM_MST_ITEM_SINGLE_A_V TO '||R.USERNAME; V_N:=V_N+1;
    EXCEPTION WHEN OTHERS THEN DBMS_OUTPUT.PUT_LINE('SKIP GT_SDPB_DM_MST_ITEM_SINGLE_A_V '||SQLERRM); END;
    BEGIN EXECUTE IMMEDIATE 'GRANT DELETE,INSERT,SELECT,UPDATE ON SCM_MGR.GT_SDPB_DM_MST_ITEM_SINGLE_B_V TO '||R.USERNAME; V_N:=V_N+1;
    EXCEPTION WHEN OTHERS THEN DBMS_OUTPUT.PUT_LINE('SKIP GT_SDPB_DM_MST_ITEM_SINGLE_B_V '||SQLERRM); END;
    BEGIN EXECUTE IMMEDIATE 'GRANT DELETE,INSERT,SELECT,UPDATE ON SCM_MGR.GT_SDPB_DM_MST_ITEM_SINGLE_ORI TO '||R.USERNAME; V_N:=V_N+1;
    EXCEPTION WHEN OTHERS THEN DBMS_OUTPUT.PUT_LINE('SKIP GT_SDPB_DM_MST_ITEM_SINGLE_ORI '||SQLERRM); END;
    BEGIN EXECUTE IMMEDIATE 'GRANT DELETE,INSERT,SELECT,UPDATE ON SCM_MGR.GT_SDPB_DM_MST_ITEM_SINGLE_V TO '||R.USERNAME; V_N:=V_N+1;
    EXCEPTION WHEN OTHERS THEN DBMS_OUTPUT.PUT_LINE('SKIP GT_SDPB_DM_MST_ITEM_SINGLE_V '||SQLERRM); END;
    BEGIN EXECUTE IMMEDIATE 'GRANT DELETE,INSERT,SELECT,UPDATE ON SCM_MGR.GT_SDPB_FUTURE_PRICE_TEMP_QTY TO '||R.USERNAME; V_N:=V_N+1;
    EXCEPTION WHEN OTHERS THEN DBMS_OUTPUT.PUT_LINE('SKIP GT_SDPB_FUTURE_PRICE_TEMP_QTY '||SQLERRM); END;
    BEGIN EXECUTE IMMEDIATE 'GRANT DELETE,INSERT,SELECT,UPDATE ON SCM_MGR.GT_T_MAIL_ADDR TO '||R.USERNAME; V_N:=V_N+1;
    EXCEPTION WHEN OTHERS THEN DBMS_OUTPUT.PUT_LINE('SKIP GT_T_MAIL_ADDR '||SQLERRM); END;
  END LOOP;
  DBMS_OUTPUT.PUT_LINE('GRANT 실행 '||V_N||' (계정수 x 오브젝트수)');
  IF V_N=0 THEN RAISE_APPLICATION_ERROR(-20001,
    'SCMP_APP / SCMD_APP 둘 다 없음 — 이 환경의 애플리케이션 계정 확인 후 수동 GRANT'); END IF;
END;
/

