SELECT GRANTEE, COUNT(*) CNT FROM ALL_TAB_PRIVS
 WHERE TABLE_NAME IN ('PKG_DMF0003','PKG_DMF0020','PKG_DMF0021','PKG_DMF0042','PKG_DMF0044','PKG_DMF0049','PKG_DMF0082','DMF0020_SAVE_SCM_MST_FUTURE_PRICE_ALL','DMF0020_SAVE_SCM_MST_FUTURE_PRICE_POPUP')
